pub(super) fn matches(bytes: &[u8]) -> bool {
    HEADERS
        .iter()
        .any(|(n, h)| bytes.len() == *n && bytes.get(..64) == Some(&h[..]))
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn exceptions_require_every_header_byte_and_exact_extent() {
        for (n, h) in HEADERS {
            let mut bytes = vec![0; *n];
            bytes[..64].copy_from_slice(h);
            assert!(matches(&bytes));
            for offset in 0..64 {
                bytes[offset] ^= 1;
                assert!(!matches(&bytes));
                bytes[offset] ^= 1;
            }
            assert!(!matches(&bytes[..bytes.len() - 1]));
            bytes.push(0);
            assert!(!matches(&bytes));
        }
    }
}
